mapper.select:
SELECT id, pattern_type, pattern_text, source_finding_id, source_url, required_terms, memo, created_at, updated_at FROM t_cleanroom WHERE 1=1
AND pattern_type = #{pattern_type}
ORDER BY id DESC

mapper.update:
UPDATE t_cleanroom
SET 
    pattern_text = #{pattern_text},
    updated_at = datetime('now', 'localtime')

        , required_terms = #{required_terms}


        , memo = #{memo}

WHERE id = #{id}

mapper.select:
SELECT id, pattern_type, pattern_text, memo
FROM t_cleanroom
WHERE TRIM(pattern_text) = #{pattern_text}

SELECT id, pattern_type, pattern_text, memo
FROM t_cleanroom
WHERE TRIM(pattern_text) = #{pattern_text}
  AND id != #{exclude_id}
